          quiz:[{type:'choice',q:'角有几个顶点？',options:['1个','2个','3个','没有'],answer:0},{type:'choice',q:'角的大小与什么有关？',options:['边的长短','两边张开的大小','顶点的位置','都有关'],answer:1},{type:'choice',q:'三角尺上最大的角是？',options:['锐角','直角','钝角','平角'],answer:1},{type:'choice',q:'比直角小的角叫？',options:['锐角','直角','钝角','平角'],answer:0},{type:'choice',q:'角有几条边？',options:['1条','2条','3条','4条'],answer:1}],
