          quiz:[{type:'choice',q:'收集数据的方法有？',options:['调查法','投票法','观察法','都可以'],answer:3},{type:'choice',q:'记录数据时常用什么方法？',options:['画正字','画圈','打勾','都可以'],answer:3},{type:'choice',q:'统计表的作用是？',options:['好看','清楚展示数据','好玩','好拿'],answer:1},{type:'choice',q:'一个"正"字代表几票？',options:['3票','4票','5票','6票'],answer:2},{type:'choice',q:'收集数据时要注意？',options:['不重复','不遗漏','记录清楚','都要注意'],answer:3}],
