          quiz:[{type:'choice',q:'12是3的几倍？',options:['2倍','3倍','4倍','5倍'],answer:2},{type:'choice',q:'5的4倍是多少？',options:['15','20','25','30'],answer:1},{type:'choice',q:'求一个数是另一个数的几倍用？',options:['加法','减法','乘法','除法'],answer:3},{type:'choice',q:'求一个数的几倍是多少用？',options:['加法','减法','乘法','除法'],answer:2},{type:'choice',q:'18是6的几倍？',options:['2倍','3倍','4倍','5倍'],answer:1}],
