          quiz:[{type:'choice',q:'20×3=?',options:['50','60','70','80'],answer:1},{type:'choice',q:'123×3=?',options:['359','369','379','389'],answer:1},{type:'choice',q:'300×4=?',options:['1000','1100','1200','1300'],answer:2},{type:'choice',q:'24×5=?',options:['100','110','120','130'],answer:2},{type:'choice',q:'105×6=?',options:['600','610','620','630'],answer:3}],
