          quiz:[{type:'choice',q:'四边形有几条边？',options:['3条','4条','5条','6条'],answer:1},{type:'choice',q:'长方形周长公式是？',options:['长+宽','(长+宽)×2','长×宽','边长×4'],answer:1},{type:'choice',q:'正方形周长公式是？',options:['边长+边长','边长×2','边长×4','边长×边长'],answer:2},{type:'choice',q:'长8宽5的长方形周长是？',options:['13厘米','26厘米','39厘米','52厘米'],answer:1},{type:'choice',q:'边长6的正方形周长是？',options:['12厘米','18厘米','24厘米','36厘米'],answer:2}],
